# ---- card names (French -> official English) ----
raw = re.findall(r'\["(\w+)","(Gem|Relic|Spell)","(\w+)",(\d+),"([^"]*)","([^"]*)","([^"]*)"', html)
special = {"SiftersPearl": "Sifter's Pearl", "MagesTalisman": "Mage's Talisman", "VriswoodAmber": "V'riswood Amber"}
for r in raw:
    en = r[5] or special.get(r[0]) or re.sub(r'(?<=[a-z])(?=[A-Z])', ' ', r[0])
    if r[4]:
        M[r[4]] = en

